#!/bin/sh
set -eu
# Stub llvm-tblgen for OHOS SDK (no TableGen binary available)
# Generates stub .inc files so the build can proceed without TableGen.
# The actual Enzyme .inc files contain derivative rules generated by
# enzyme-tblgen from TableGen descriptions. Since OHOS SDK LLVM doesn't
# include TableGen, we provide stubs that return false/empty.
# IMPORTANT: this file MUST be executable (chmod +x). Otherwise
# execute_process() hits "permission denied" and produces empty files,
# causing compile errors at CallDerivatives.cpp:2254 (handleBLAS
# undeclared) and Utils.cpp:410 (attributeTablegen undeclared).
output_file=""
input_file=""
gen_type=""
while [ $# -gt 0 ]; do
    case "$1" in
        -o) shift; output_file="$1" ;;
        -d) shift ;; # depfile, skip
        --*) ;; # other flags, skip
        -gen-*) gen_type="$1" ;;
        *)
            if [ -z "$input_file" ] && [ -f "$1" ] 2>/dev/null; then
                input_file="$1"
            fi
            ;;
    esac
    shift
done

if [ -z "$output_file" ]; then
    exit 0
fi

mkdir -p "$(dirname "$output_file")" 2>/dev/null

# Generate appropriate content based on the output filename
basename=$(basename "$output_file")

case "$basename" in
    BlasDerivatives.inc)
        # handleBLAS(llvm::CallInst &call, llvm::Function *called, BlasInfo blas, ...)
        cat > "$output_file" << 'EOF'
// Auto-generated stub for OHOS SDK (no TableGen available)
// BLAS derivative rules: returning false (not a BLAS call)
static bool handleBLAS(llvm::CallInst &call, llvm::Function *called, BlasInfo blas, const std::vector<bool> &) {
    (void)call; (void)called; (void)blas;
    return false;
}
EOF
        ;;
    CallDerivatives.inc)
        # handleCallDerivatives - stub that returns false
        cat > "$output_file" << 'EOF'
// Auto-generated stub for OHOS SDK (no TableGen available)
// Call derivative rules: returning false (no match)
EOF
        ;;
    BinopDerivatives.inc)
        cat > "$output_file" << 'EOF'
// Auto-generated stub for OHOS SDK (no TableGen available)
// Binary operation derivative rules: stub
EOF
        ;;
    IntrinsicDerivatives.inc)
        cat > "$output_file" << 'EOF'
// Auto-generated stub for OHOS SDK (no TableGen available)
// Intrinsic derivative rules: stub
EOF
        ;;
    InstructionDerivatives.inc)
        cat > "$output_file" << 'EOF'
// Auto-generated stub for OHOS SDK (no TableGen available)
// Instruction derivative rules: stub
EOF
        ;;
    BlasAttributor.inc)
        cat > "$output_file" << 'EOF'
// Auto-generated stub for OHOS SDK (no TableGen available)
// BLAS attributor rules: stub that returns false (no changes)
static bool attributeTablegen(llvm::Function &F) {
    return false;
}
EOF
        ;;
    BlasTA.inc)
        cat > "$output_file" << 'EOF'
// Auto-generated stub for OHOS SDK (no TableGen available)
// BLAS type analysis rules: stub
EOF
        ;;
    BlasDiffUse.inc)
        cat > "$output_file" << 'EOF'
// Auto-generated stub for OHOS SDK (no TableGen available)
// BLAS differential use analysis rules: stub
EOF
        ;;
    *)
        # Default: empty stub
        echo "/* Auto-generated stub for OHOS SDK (no TableGen available) */" > "$output_file"
        echo "// Generated by stub llvm-tblgen for OHOS" >> "$output_file"
        ;;
esac
exit 0